import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.IIAdu7fg.js";const g=JSON.parse('{"title":"2026-10-29 Agent 核心研究与竞品动态","description":"可验证声明、执行与凭据归属、断线证据、永久幂等身份与版本交付边界。","frontmatter":{"title":"2026-10-29 Agent 核心研究与竞品动态","description":"可验证声明、执行与凭据归属、断线证据、永久幂等身份与版本交付边界。"},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-10-29.md","filePath":"zh/runtime/daily-intelligence/2026-10-29.md","lastUpdated":1793250121000}'),n={name:"zh/runtime/daily-intelligence/2026-10-29.md"};function i(l,e,s,p,c,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_2026-10-29-agent-核心研究与竞品动态" tabindex="-1">2026-10-29 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-10-29-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-10-29 Agent 核心研究与竞品动态&quot;">​</a></h1><p>本轮最重要的结论是：<strong>成功声明需要回执与状态证据，复用连接与恢复流程必须保留执行/凭据 owner，清理历史也不能让旧操作重新获得执行身份。</strong> 赵越本轮收录的研究与工具、Codex 的 per-chat MCP lease、Paperclip 的恢复写入和 Beads 的永久 tombstone 在这些主题上形成共振。OpenHands SDK 与 Orca 有正式交付推进；AutoGen 则新增明确的维护终止声明。</p><p>实际执行起点：2026-10-29 12:47:01（Asia/Shanghai）。主要增量窗口从上轮成功核查起点 2026-10-28 11:18:02 至本次起点；依据逐来源检查点及已发布日档去重。部分来源保留更早 pending window。旧论文仅按“本轮新收录”报告，原发表日期单列。所有 CodeFlowMu/FCoP 关联为<strong>待验证线索</strong>，不等于本地缺陷、完成实验或开发派工。</p><h2 id="_1-赵越-新收录可验证声明、类型协议与-coding-agent-安全资源" tabindex="-1">1. 赵越：新收录可验证声明、类型协议与 coding-agent 安全资源 <a class="header-anchor" href="#_1-赵越-新收录可验证声明、类型协议与-coding-agent-安全资源" aria-label="Permalink to &quot;1. 赵越：新收录可验证声明、类型协议与 coding-agent 安全资源&quot;">​</a></h2><p><strong>状态：NEW CURATION / COMMITTED; PAPERS PREDATE THIS WINDOW</strong></p><p>awesome-auditable-ai 的本轮提交新增 Concordat、V³AST-Bench、agent-claimcheck，并接入经维护者修订的 SciΠvot；这是赵越的收录，不把这些论文和工具归为其本人作品。Concordat 原发 10 月 27 日，用有限状态协议在副作用前限制可用工具；50 个航空任务中，标准 gpt-4.1 Agent 有 13 个任务出现未确认修改，受约束 Agent 为 0。V³AST-Bench 原发 26 日，用 212 个风险任务及 capability twins 区分“安全”与“不会做”。SciΠvot 原发 15 日，是从人工纠正点选择的 248 例，不能把其中四个模型低于随机的结果推广到一般科研任务。</p><p>agent-claimcheck 对成功声明核对工具回执和调用者提供的状态 probe；规则路径 receipt_only 的 0.70 分低于 verified 的 0.80 门槛，但其 300 条基准是合成且与规则共同设计，不能当真实误报率。agent-config 另新增研究写作 handoff，要求固定来源、不改全局配置，并区分风格检查与事实核验。FCoP 待验证：完成声明、授权合规和任务能力需独立证据；值得互动的是独立真实轨迹验证、probe 信任和选择偏差。</p><p>原始来源：<a href="https://github.com/yzhao062/awesome-auditable-ai/commit/4583670fdbe6aafd98543d48b4a3f26fda1e68f8" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://arxiv.org/abs/2610.37461" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://arxiv.org/abs/2610.35188" target="_blank" rel="noreferrer">证据 3</a> · <a href="https://arxiv.org/abs/2610.21082" target="_blank" rel="noreferrer">证据 4</a> · <a href="https://github.com/B0yko/agent-claimcheck" target="_blank" rel="noreferrer">证据 5</a> · <a href="https://github.com/yzhao062/agent-config/blob/6a375896f210542d622e1bcc4ba58e8dfde7a286/docs/writing-harness-handoff.md" target="_blank" rel="noreferrer">证据 6</a></p><h2 id="_2-autogen-官方不再维护声明已合入-仓库-archived-标志仍为-false" tabindex="-1">2. AutoGen：官方不再维护声明已合入，仓库 archived 标志仍为 false <a class="header-anchor" href="#_2-autogen-官方不再维护声明已合入-仓库-archived-标志仍为-false" aria-label="Permalink to &quot;2. AutoGen：官方不再维护声明已合入，仓库 archived 标志仍为 false&quot;">​</a></h2><p><strong>状态：MAINTENANCE NOTICE COMMITTED; REPOSITORY archived=false</strong></p><p>microsoft/autogen 提交 d07c667 在文档首页加入官方 caution：Microsoft 不再提供 bug/security fixes、新功能和支持，建议新用户从 Microsoft Agent Framework 开始，现有用户参考迁移指南。需要区分两件事：文案称项目 archived/no longer maintained，但本轮 GitHub repo API 的 archived=false；不能说 API 已变只读，也不能用该标志否定维护终止声明。</p><p>待验证线索：框架选型和长期运行依赖需要核查维护承诺，而非只看 star 或 API archived。继续保存原研究对象与历史事实。值得互动：迁移中的会话、工具、审批和持久状态兼容范围；本轮没有实施迁移。</p><p>原始来源：<a href="https://github.com/microsoft/autogen/commit/d07c667a3239ea4ab7af62a53b0f4ff205a1f23d" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/microsoft/autogen" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_3-codex-main-共享-mcp-连接增加每-chat-租约-guardian-评估不授予执行权" tabindex="-1">3. Codex main：共享 MCP 连接增加每 chat 租约，Guardian 评估不授予执行权 <a class="header-anchor" href="#_3-codex-main-共享-mcp-连接增加每-chat-租约-guardian-评估不授予执行权" aria-label="Permalink to &quot;3. Codex main：共享 MCP 连接增加每 chat 租约，Guardian 评估不授予执行权&quot;">​</a></h2><p><strong>状态：MERGED #57978/#57757; STABLE INCLUSION NOT VERIFIED</strong></p><p>#57978 对声明支持 codex/connection-lease 的 pooled stdio server，为每个 chat 建独立租约；host-owned lease ID 覆盖调用者传入的同名 metadata。释放前先写 pending request cancellation，cleanup 失败或超时即移出连接池；不支持扩展的 server 保持原行为。#57757 将 Guardian assessment 作为带 response_id/item_id/requires_review 的 SSE/WebSocket 事件交付，字段损坏时忽略该 assessment；它不进入对话历史，也不授权工具执行。稳定版仍为 0.165.0，新 alpha 不等于这些合入项已稳定交付。</p><p>CodeFlowMu 待验证：连接复用不能抹掉会话所有权，观测事件与授权事实不能混用。值得互动：一 chat 释放时其他 chat 的存活、取消/释放顺序，以及丢失评估事件时如何保持授权闭合。</p><p>原始来源：<a href="https://github.com/openai/codex/pull/57978" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/openai/codex/pull/57757" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_4-openai-agents-js-sandbox-环境解析可归客户端所有" tabindex="-1">4. OpenAI Agents JS：sandbox 环境解析可归客户端所有 <a class="header-anchor" href="#_4-openai-agents-js-sandbox-环境解析可归客户端所有" aria-label="Permalink to &quot;4. OpenAI Agents JS：sandbox 环境解析可归客户端所有&quot;">​</a></h2><p><strong>状态：MERGED #2085; RELEASE NOT VERIFIED</strong></p><p>#2085 增加 SandboxClient.environmentPreparation=&#39;client&#39;，覆盖创建、显式 resume、RunState resume 和保留 session 复用。runner 保留未解析 references，避免 Temporal workflow 获取 worker 环境 allowlist 和实际 secrets；既有 trusted mount/path policy 仍权威，provider state 身份保留。sandbox envelope 升至 v6 并记录 owner；旧 v5 仍可读，存在 v6 时 RunState 用 schema 1.24，resume 与最终 authority binding 共用状态事务。</p><p>待验证线索：编排上下文、执行环境和密钥解析者是不同角色；恢复不应偷偷转移环境准备权。值得互动：v5/v6 重序列化、失败恢复回滚与跨客户端 owner 检查。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-js/pull/2085" target="_blank" rel="noreferrer">证据 1</a></p><h2 id="_5-openhands-sdk-1-59-0-预算、恢复和脱敏修复正式发行" tabindex="-1">5. OpenHands SDK 1.59.0：预算、恢复和脱敏修复正式发行 <a class="header-anchor" href="#_5-openhands-sdk-1-59-0-预算、恢复和脱敏修复正式发行" aria-label="Permalink to &quot;5. OpenHands SDK 1.59.0：预算、恢复和脱敏修复正式发行&quot;">​</a></h2><p><strong>状态：RELEASED; STATE ADVANCE FROM PREVIOUS MERGES</strong></p><p>v1.59.0 明确包含 #6257/#6279 的会话预算和客户端可见状态、#6197 缺损日志容错加载、#6155/#6259 的 ID/时间戳脱敏保护，以及重放 OAuth callback 返回已保存 job 状态。这将前几轮“已合入、发行未确认”的多项能力推进到正式版本。预算仍按会话累计并在 step 间检查，可能超一次模型调用；容错加载不证明日志完整。enyst 仍直接参与预算、OAuth 和子会话工作。</p><p>待验证线索：现在有明确发行版本可作为复现基线，但不能把“正式发行”换成“本地验收完成”。值得互动：缺口 warning 如何成为上层验证证据、累计预算和子 Agent 成本的显示。</p><p>原始来源：<a href="https://github.com/OpenHands/software-agent-sdk/releases/tag/v1.59.0" target="_blank" rel="noreferrer">证据 1</a></p><h2 id="_6-openhands-canvas-后端-secret-consent-绑定-revision-与确切名称" tabindex="-1">6. OpenHands Canvas 后端：secret consent 绑定 revision 与确切名称 <a class="header-anchor" href="#_6-openhands-canvas-后端-secret-consent-绑定-revision-与确切名称" aria-label="Permalink to &quot;6. OpenHands Canvas 后端：secret consent 绑定 revision 与确切名称&quot;">​</a></h2><p><strong>状态：MERGED SDK #6041; CANVAS #18572 OPEN; RELEASE NOT VERIFIED</strong></p><p>#6041 允许 managed App 后端声明所需 secret 名称，用户同意绑定 installed revision 和确切名称，任一变化需重新同意；实际值仅启动时由加密存储解析，不进 manifest/browser bundle。启用需准备、启动并等 health，失败保持 disabled；撤销 secrets 会清 consent 并停 app。它合入晚于 1.59.0 发行，不能归入该版本。配套 Canvas #18572 本轮仍 OPEN，前端完整交付未确认；上游有人工作队列实测，不是本地安全全验收。</p><p>待验证线索：安装、页面加载、运行和密钥授权必须分别成事实；批准对象应包含版本。值得互动：revision 变化、撤销与崩溃重启的竞态，以及日志分块脱敏的残留边界。</p><p>原始来源：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6041" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/OpenHands/OpenHands/pull/18572" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_7-paperclip-可恢复-transcript-已合入-断线写入绑定原账户与目标" tabindex="-1">7. Paperclip：可恢复 transcript 已合入，断线写入绑定原账户与目标 <a class="header-anchor" href="#_7-paperclip-可恢复-transcript-已合入-断线写入绑定原账户与目标" aria-label="Permalink to &quot;7. Paperclip：可恢复 transcript 已合入，断线写入绑定原账户与目标&quot;">​</a></h2><p><strong>状态：MERGED #17456/#17960/#18037; RELEASE NOT VERIFIED</strong></p><p>昨天仍 OPEN 的 #17456 已合入：按可见 view 的 interest 共享连接，先订阅再 catch-up，以 sequence/log identity 去重；队列最多 1000 项/1 MiB，溢出需 resync，浏览器 interest 不改变执行、ACK、checkpoint 或授权。#17960 的写入恢复保留原账户、task 和请求 key，只有服务端有幂等契约才自动重试，不确定结果先核回执，账户切换会取消旧工作。#18037 给管理员提供有界 upgradeReadiness 观察，缺 owner/checkpoint 或读取不完整时不能给正面结论；不等于异构升级验收已完成。</p><p>学习价值高、竞争风险高，提高主雷达的断线恢复和证据可见性权重。FCoP 待验证：重连成功、写入持久化和热升级可接管不是同一事实。值得互动：权限撤销后的追帧、回执与重试竞赛，以及 pending/conflict/manual retry 的状态收敛。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/17456" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/17960" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/paperclipai/paperclip/pull/18037" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="_8-paperclip-默认关闭的-coordinator-将对话、任务与决策绑定" tabindex="-1">8. Paperclip：默认关闭的 Coordinator 将对话、任务与决策绑定 <a class="header-anchor" href="#_8-paperclip-默认关闭的-coordinator-将对话、任务与决策绑定" aria-label="Permalink to &quot;8. Paperclip：默认关闭的 Coordinator 将对话、任务与决策绑定&quot;">​</a></h2><p><strong>状态：MERGED #17983; EXPERIMENT DEFAULT OFF; RELEASE NOT VERIFIED</strong></p><p>#17983 新增个人可选 Coordinator workspace，不替换 classic。每 Agent 一条 conversation，任务建议/创建链接回原对话，Questions、decision receipts、exact review targets 和 history 复用 canonical task/interaction 记录，集中 Needs You 队列；仍保留 task access、assignment authorization、revision binding 和输出 review gate。API merged_at 已确认合入，PR 描述中遗留“unmerged”的过程文字不能覆盖实际状态；本轮无新 live provider 验收。</p><p>学习价值中高、竞争风险中高，维持主雷达并提高数字员工/决策模型关注。CodeFlowMu 待验证：跨表面的决定应有一个事实 owner，而不是多份按钮状态。值得互动：revision 已变化后旧审阅卡的处理和跨账户偏好隔离。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/17983" target="_blank" rel="noreferrer">证据 1</a></p><h2 id="_9-orca-1-4-243-244-宿主升级进入发行-旧进程仍有生效边界" tabindex="-1">9. Orca 1.4.243/244：宿主升级进入发行，旧进程仍有生效边界 <a class="header-anchor" href="#_9-orca-1-4-243-244-宿主升级进入发行-旧进程仍有生效边界" aria-label="Permalink to &quot;9. Orca 1.4.243/244：宿主升级进入发行，旧进程仍有生效边界&quot;">​</a></h2><p><strong>状态：RELEASED</strong></p><p>1.4.243 让新终端使用新 terminal host，旧终端继续挂在旧 host；1.4.244 沿用 243 的 host，部分已合入终端修复要等 host 重启才生效。243 可在退出 CLI agent 后将原会话继续到 Chat，支持调整/关闭新派发 worker heartbeat；244 修复多 Agent Codex 本地历史膨胀到 GB，并改进 WSL/远程文件恢复。手机安装入口从 TestFlight 转 App Store，Android 仍 APK；Chrome browser extensions 仍实验性、默认关闭。</p><p>学习价值高、竞争风险中高，保持第二圈重点，提高安装交付、手机与 worker lifecycle 权重。待验证：app 已更新不代表所有存活进程已换代。值得互动：旧 host 的剩余风险提示、worker 配置代际和远端版本协商。</p><p>原始来源：<a href="https://github.com/stablyai/orca/releases/tag/v1.4.243" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/stablyai/orca/releases/tag/v1.4.244" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_10-orca-插件同意绑定确切字节-alpha-主干合入晚于正式版" tabindex="-1">10. Orca：插件同意绑定确切字节；Alpha 主干合入晚于正式版 <a class="header-anchor" href="#_10-orca-插件同意绑定确切字节-alpha-主干合入晚于正式版" aria-label="Permalink to &quot;10. Orca：插件同意绑定确切字节；Alpha 主干合入晚于正式版&quot;">​</a></h2><p><strong>状态：GROUNDWORK IN 1.4.244, PLUGINS OFF BY DEFAULT; #35470 MERGED LATER</strong></p><p>1.4.244 的 groundwork 包含 #30636 的无 checkout 下载和 catalog 精确版本 pin，以及 #30637 的 worker/panel approval 内容哈希。每次启动/崩溃重启前不缓存地检查内容与 consent，更新后的运行 worker 经同路径重启；已在运行的复用 worker 不重复 hash，本地开发目录也不绑字节。完整 Plugin Alpha #35470 于 03:58 UTC 合入，比 244 的 03:55 发行晚，不能说完整 Alpha 已随 244 发布；新增编辑器/语法等仍须区分状态。</p><p>学习价值高、竞争风险中高，第二圈提高插件信任/交付关注。CodeFlowMu 待验证：下载、安装、批准、启动和自动更新各有不同权限边界。值得互动：开发模式例外、运行中代码变化和崩溃重启之间的 TOCTOU。</p><p>原始来源：<a href="https://github.com/stablyai/orca/pull/30636" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/stablyai/orca/pull/30637" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/stablyai/orca/pull/35470" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="_11-beads-永久-tombstone-阻止清理后的迟到重试复活操作" tabindex="-1">11. Beads：永久 tombstone 阻止清理后的迟到重试复活操作 <a class="header-anchor" href="#_11-beads-永久-tombstone-阻止清理后的迟到重试复活操作" aria-label="Permalink to &quot;11. Beads：永久 tombstone 阻止清理后的迟到重试复活操作&quot;">​</a></h2><p><strong>状态：MERGED #7931/#7902/#7983; RELEASE NOT VERIFIED</strong></p><p>#7931 在明确 retain-ids 的 sweep 中，与删除同事务写永久 (id, closed_at) tombstone；后续 create/rename 等返回 410 idempotency_expired，import 跳过并报告，生成 ID 也避开。普通 prune/purge/delete/gc 不自动退休 ID，因此不能称所有清理都防重。#7902 要求证明 localhost Dolt server 真服务该 workspace 目录，reset-data 保留 remote；#7983 先 dry-run 依赖检查再复制迁移，防止半迁移双份，并修 dry-run 与真实删除集合不一致。</p><p>学习价值高、竞争风险中，保持主雷达恢复/存储观察。FCoP 待验证：证据保留窗口结束不能让幂等键重新变成可执行新操作；localhost 也不是数据身份。值得互动：tombstone 增长、永久身份与隐私删除，以及迁移预检到提交的竞争。</p><p>原始来源：<a href="https://github.com/gastownhall/beads/pull/7931" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/gastownhall/beads/pull/7902" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/gastownhall/beads/pull/7983" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="_12-dspy-3-5-主干迁移-统一-request-response-litellm-可选但保留兼容" tabindex="-1">12. DSPy 3.5 主干迁移：统一 Request/Response，LiteLLM 可选但保留兼容 <a class="header-anchor" href="#_12-dspy-3-5-主干迁移-统一-request-response-litellm-可选但保留兼容" aria-label="Permalink to &quot;12. DSPy 3.5 主干迁移：统一 Request/Response，LiteLLM 可选但保留兼容&quot;">​</a></h2><p><strong>状态：SIX-PR STACK MERGED; RELEASE/PARITY NOT VERIFIED</strong></p><p>#10652 等六个 PR 将 adapter/custom engine 统一到 Request→Response，移除旧 messages=/forward/aforward 接入，旧缓存重算而非迁移，字符串便捷调用仍返回列表。最终 #10719 的实际方案是 LiteLLM 改为可选 extra、保留兼容 engine；auto 在请求前选择，provider 失败不触发换 backend，不是完全删除 LiteLLM。native Chat audio/files、Anthropic citation fidelity、部分 provider parity 及重复候选计费差异仍有开放 gate，不能把主干合入称成 3.5 正式发布或等价迁移。</p><p>待验证线索：统一契约可收敛计费/缓存/历史，但兼容层和不同 provider 的语义不能凭接口统一假定等价。值得互动：已计费失败的 usage 留存、候选调用次数、endpoint/credential 保持以及旧缓存失效。</p><p>原始来源：<a href="https://github.com/stanfordnlp/dspy/pull/10652" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/stanfordnlp/dspy/pull/10719" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/stanfordnlp/dspy/pull/10708" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="_13-phoenix-vibe-kanban-权限声明还要接通实际-executor-路径" tabindex="-1">13. Phoenix / Vibe Kanban：权限声明还要接通实际 executor 路径 <a class="header-anchor" href="#_13-phoenix-vibe-kanban-权限声明还要接通实际-executor-路径" aria-label="Permalink to &quot;13. Phoenix / Vibe Kanban：权限声明还要接通实际 executor 路径&quot;">​</a></h2><p><strong>状态：MERGED #15828 / #3487; RELEASE NOT VERIFIED</strong></p><p>Phoenix #15828 即使主 run bypass edit approval，也令子 Agent 保持只读；MCP tools/list 失败只记录异常类别并降级，避免原始 transport 错误带出 bearer header；登出清除 deployment-scope 浏览器 PAT，防止共享机器下一用户继承。Vibe Kanban #3487 补上 Copilot 到 ExecutorApprovalBridge 的路由：之前 Supervised 声明虽关闭 allow_all_tools，却因落到 NoopApprovalService 静默自动批准。两者未确认进入正式版。</p><p>CodeFlowMu 待验证：UI policy、backend flag 和 executor bridge 都要闭合，不能只检查设置值。值得互动：新增 executor 的审批 conformance、跨用户凭据清理和降级后的权限。Vibe 学习价值高但竞争风险低，维持 sunset 历史样本低频判断，不由一条修复推断商业恢复。</p><p>原始来源：<a href="https://github.com/Arize-ai/phoenix/pull/15828" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/BloopAI/vibe-kanban/pull/3487" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_14-uniemployee-0-24-0-持续-rss-采集、原文版本与中断恢复正式交付" tabindex="-1">14. UniEmployee 0.24.0：持续 RSS 采集、原文版本与中断恢复正式交付 <a class="header-anchor" href="#_14-uniemployee-0-24-0-持续-rss-采集、原文版本与中断恢复正式交付" aria-label="Permalink to &quot;14. UniEmployee 0.24.0：持续 RSS 采集、原文版本与中断恢复正式交付&quot;">​</a></h2><p><strong>状态：RELEASED</strong></p><p>0.24.0 增加 RSS 信源管理、清单导入预览、单源试抓、持续采集批次、原文版本与待核验资料页，启动恢复中断任务。信源需管理员显式导入或配置后才启用，相关表启动时幂等创建。新增可编辑 PPT 生成与会话预览，但依赖部署端生成 runtime；缺失时交付内容稿，不是完整 PPT 能力。RAGFlow 不可用时返回明确状态并继续使用其他资料；测试通过为上游发行声明，本轮未安装。</p><p>学习价值高、竞争风险中高，提高第二圈垂直研究产品关注。CodeFlowMu/FCoP 待验证：采集批次、原文版本、未核验材料和生成交付需独立状态。值得互动：恢复去重、信源启停授权及 PPT runtime 缺失时的交付契约。</p><p>原始来源：<a href="https://github.com/zj-unicom-ai/UniEmployee/releases/tag/v0.24.0" target="_blank" rel="noreferrer">证据 1</a></p><h2 id="_15-mcp-旧版-initialize-的扩展协商得到文档澄清-规范-schema-未改" tabindex="-1">15. MCP：旧版 initialize 的扩展协商得到文档澄清，规范 schema 未改 <a class="header-anchor" href="#_15-mcp-旧版-initialize-的扩展协商得到文档澄清-规范-schema-未改" aria-label="Permalink to &quot;15. MCP：旧版 initialize 的扩展协商得到文档澄清，规范 schema 未改&quot;">​</a></h2><p><strong>状态：MERGED #3364; DOCUMENTATION ONLY</strong></p><p>#3364 补充 2025-11-25 等 initialization-based 版本如何在 initialize capabilities 中携带 extensions，区别于 2026-07-28 之后的 per-request capability 流。旧发布 schema 没有该字段，也不是旧协议 conformance 必须项；要核查 SDK 是否保留字段及具体 extension 的兼容，并在缺失时降级。PR 的 9/10 SDK 主干审计是上游截至 10 月 27 日的源码核对，不代表所有已发布包或所有扩展都可用。</p><p>待验证线索：核心协议版本、SDK capability 透传和扩展支持是三层事实。值得互动：legacy negotiation 的双向保留测试、未知字段被验证器丢弃时的可观测性，以及 Apps/Skills 逐扩展验收。</p><p>原始来源：<a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/3364" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://modelcontextprotocol.io/extensions/overview" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_16-langgraph-sdk-重连加退避-无-cursor-时明确警告事件缺口" tabindex="-1">16. LangGraph SDK：重连加退避，无 cursor 时明确警告事件缺口 <a class="header-anchor" href="#_16-langgraph-sdk-重连加退避-无-cursor-时明确警告事件缺口" aria-label="Permalink to &quot;16. LangGraph SDK：重连加退避，无 cursor 时明确警告事件缺口&quot;">​</a></h2><p><strong>状态：MERGED #9481/#9482/#9477; RELEASE NOT VERIFIED</strong></p><p>#9481 让 wait/join/cancel(wait=True) 的中断响应重连在五次预算内退避重试 429/5xx/连接失败，初始请求失败和其他状态仍直接报错。#9482 对没有 Last-Event-ID 的重连发 warning：后续事件能继续来，但断线期间不能回放，不能宣称无损。#9477 进一步保留跨 chunk SSE 空 data/CR 行和解码 cursor；不声称穷尽规范符合性。</p><p>FCoP 待验证：连接恢复不能被自动记为轨迹完整，warning 应进入覆盖证据。值得互动：缺口怎样影响恢复判断、外部 cursor 的可信来源和不同客户端的重放一致性。</p><p>原始来源：<a href="https://github.com/langchain-ai/langgraph/pull/9481" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/langchain-ai/langgraph/pull/9482" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/langchain-ai/langgraph/pull/9477" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="_17-google-adk-截断-claude-tool-call-不再执行-统一拒绝歧义-url" tabindex="-1">17. Google ADK：截断 Claude tool call 不再执行，统一拒绝歧义 URL <a class="header-anchor" href="#_17-google-adk-截断-claude-tool-call-不再执行-统一拒绝歧义-url" aria-label="Permalink to &quot;17. Google ADK：截断 Claude tool call 不再执行，统一拒绝歧义 URL&quot;">​</a></h2><p><strong>状态：COMMITTED ON MAIN; RELEASE NOT VERIFIED</strong></p><p>b9d2bc3（#7558）在 Claude tool_use 被 max_tokens 或 model_context_window_exceeded 截断时返回 MAX_TOKENS 且 content=None，避免执行不完整参数，也覆盖用工具承载的结构化输出。4d0cd98 拒绝 authority 含反斜杠的 model-supplied URL，修复代理下 URL parser 检查 example.com、实际 HTTP client 却发向 metadata host 的分歧，覆盖 load_web_page、RestApiTool、computer use。这里是上游代码事实，非本地漏洞复现。</p><p>待验证线索：解析完成和实际发送目标都要在副作用前确定；模型可修正错误不代表可以先执行半个调用。值得互动：代理、重定向和 parser 归一化一致性，截断后的 retry 是否保留原调用身份。</p><p>原始来源：<a href="https://github.com/google/adk-python/commit/b9d2bc3d95487ecc4a437b813f9b8fa634e1be54" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/google/adk-python/commit/4d0cd985faedb3c0d9e3579077de327a6ef86a52" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_18-ag2-删链接不删目标-skill-安装恢复可执行位并选对-windows-python" tabindex="-1">18. AG2：删链接不删目标，skill 安装恢复可执行位并选对 Windows Python <a class="header-anchor" href="#_18-ag2-删链接不删目标-skill-安装恢复可执行位并选对-windows-python" aria-label="Permalink to &quot;18. AG2：删链接不删目标，skill 安装恢复可执行位并选对 Windows Python&quot;">​</a></h2><p><strong>状态：MERGED #3479/#3433/#3511; RELEASE NOT VERIFIED</strong></p><p>#3479 删除 symlink/Windows junction 时只删链接，拒绝把 base directory 本身递归删除；find_files 显示 dangling/目录/外指链接而不列外部内容。#3433 解压恢复普通文件的 executable bits、不恢复 setuid/setgid，避免 helper 退出 126；#3511 在 Windows 默认 LocalRuntime 用 sys.executable 执行 .py，不把本地主机解释器路径送给 remote sandbox。上游有真实脚本与对照回归，本轮未在 CodeFlowMu 重现。</p><p>待验证线索：路径授权需要区分链接位置与目标，安装权限和执行环境也是契约。值得互动：junction/父目录 symlink 的边界、归档权限提升限制和 Windows venv/远端隔离。</p><p>原始来源：<a href="https://github.com/ag2ai/ag2/pull/3479" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/ag2ai/ag2/pull/3433" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/ag2ai/ag2/pull/3511" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="跨项目共振与分类处置" tabindex="-1">跨项目共振与分类处置 <a class="header-anchor" href="#跨项目共振与分类处置" aria-label="Permalink to &quot;跨项目共振与分类处置&quot;">​</a></h2><ul><li><strong>声明与实际状态</strong>：claimcheck 的 receipt/probe、Concordat 的协议合规、V³AST 的 capability twins、Paperclip 的不确定写入核回执，分别验证不同事实，不能用一个成功分数替代。</li><li><strong>owner 与批准对象</strong>：Codex 的 per-chat lease、Agents JS 的环境准备 owner、Canvas/Orca 的 revision/内容 consent，要求复用与恢复都保留权限归属。</li><li><strong>可恢复不等于完整</strong>：LangGraph 的无 cursor warning、Paperclip 的 resync、OpenHands 的缺损日志容错，都要让缺口进入验证结论。</li><li><strong>保留与删除有执行语义</strong>：Beads 永久 tombstone 限制迟到重试；AG2 删除链接而不删目标；迁移 dry-run 必须与实际删除集合一致。</li><li><strong>发行不能代替生效核验</strong>：Orca 存活 terminal host、插件默认关闭及 Alpha 晚于发行，OpenHands Canvas companion 仍 OPEN，DSPy 主干尚有 parity/billing gate，均保留状态边界。</li></ul><p>分类结果：仅信息收集、筛选与报告。上游试验及数字按其原始范围说明，未视为本地结果。本地工程实验 0、文章 0、正式开发评审项目 0、对外评论/消息发送 0。互动议题保存为技术切口，未派工。</p><h2 id="双源核查、覆盖与缺口" tabindex="-1">双源核查、覆盖与缺口 <a class="header-anchor" href="#双源核查、覆盖与缺口" aria-label="Permalink to &quot;双源核查、覆盖与缺口&quot;">​</a></h2><p>先用已连接 GitHub 工具读取 latest main Registry：47 位研究人物，blob 8d97df65269aa2b4accd1366d1b71319f99c6efd。人物与仓库保持多对多关系。六位治理/验证研究对象及原始关系边界继续保留，本轮未确认其关联仓库有值得单列的新代码；bulbasaur-skill-cli 仍不是 AGENTSAFE 官方 Artifact。Concordat/V³AST/SciΠvot 的原作者由原论文核验，不归为赵越作品；赵越的新增是索引收录与写作 handoff。Aegis 本轮论文摘要强化既有部署/评估说明，未据此认定新实验完成。</p><p>88 个仓库目标覆盖 Registry、明确补充技术项目和 32 个竞品。增量 commit 记录 904，30 个目标有提交；57 个可访问无增量目标另读默认 head。检查 Release、近期 commit 与更新 PR/Issue，重要事件继续读原文/文档/代码。没有逐库穷尽所有 Discussion、架构文档或 License。Superset 保留原监测名称，通过同一 ID 1080370450 的 ParadevAI/Paradev 访问；并不自行替换 Registry。</p><p>明确缺口：Codex、Claude Code、Orca 的 PR/Issue 更新各查 12 页仍未完；TSA-AI-Workforce 三类接口实际 404，不推断删除/私有化。Codex 大 Release 列表传输失败，回退最新 3 个及 latest stable 成功；其稳定版仍为 0.165.0。其余 release 主要为最新 10 个，有界列表不等于完整历史。动态分页保留记录数与 unique_count；只有实际成功完成的来源查询推进自己的水位，没有统一全覆盖水位。</p><p>第二来源类型单列：实时 47 人分 12 组检索公开人物/讨论，并对 Registry 已确认 X 地址追加定向检索；原始论文、项目主页、Cursor/Audit Commons/Paradev 官方页面及 MCP 文档另行打开。搜索无法可靠定时的新个人帖未计入新增，也不代表穷尽 X。出现同名第三方账号时不猜测归属。Cursor 当前可见 10 月 20 日材料仍旧；Audit Commons 本轮可见 10 月 27 日文章，原报道早于窗口，作为历史补查线索留存，不冒充 29 日发布。三篇新增收录论文原发日期分别为 27、26、15 日；GitHub 一手工程事实可独立支撑，不把两个 GitHub 链接说成两种来源。</p><h2 id="github-存档与网站交付" tabindex="-1">GitHub 存档与网站交付 <a class="header-anchor" href="#github-存档与网站交付" aria-label="Permalink to &quot;GitHub 存档与网站交付&quot;">​</a></h2><p>中英文包含同一组 18 项事实、状态、42 个证据链接与判断。仅用已连接 GitHub 工具更新两份当日日档和两个原索引，保留原结构、日期唯一倒序和固定入口。现有页面构建与非强推 gh-pages 发布继续使用，保留原布局、公开快照、翻译缓存及其他已发布内容。最新 main/发布分支并发检查、四文件回读、对应 Pages 完成及双语线上点击验收另存本地回执，正文不预先声称上线成功。未改 Research Runtime 业务事实、调度、候选文章或生命周期状态。</p>',103)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
